/* From Uiverse.io by adamgiebl - Tags: neumorphism, button */
.__UIV_SCOPE__ button {
  color: #090909;
  padding: 0.7em 1.7em;
  font-size: 18px;
  border-radius: 0.5em;
  background: #e8e8e8;
  border: 1px solid #e8e8e8;
  transition: all .3s;
  box-shadow: 6px 6px 12px #c5c5c5,
             -6px -6px 12px #ffffff;
}

.__UIV_SCOPE__ button:hover {
  border: 1px solid white;
}

.__UIV_SCOPE__ button:active {
  box-shadow: 4px 4px 12px #c5c5c5,
             -4px -4px 12px #ffffff;
}
